* { box-sizing: border-box; }

:root {
  color-scheme: dark;
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-size: 16px;
  color: #f5f4e9;
  background: #101a2c;
}

body {
  min-width: 360px;
  min-height: 100vh;
  margin: 0;
  display: grid;
  place-items: center;
  padding: 24px 16px;
  background-color: #101a2c;
  background-image: linear-gradient(rgba(82, 112, 149, .08) 1px, transparent 1px), linear-gradient(90deg, rgba(82, 112, 149, .08) 1px, transparent 1px);
  background-size: 24px 24px;
}

.board {
  width: min(100%, 760px);
  padding: clamp(24px, 5vw, 48px);
  border: 2px solid #435a75;
  border-radius: 18px;
  background: #1a2940;
  box-shadow: 0 18px 60px #080e19aa, inset 0 0 0 5px #142137;
}

.board-header { text-align: center; }
.eyebrow { margin: 0 0 8px; color: #f7c85b; font-size: .85rem; font-weight: 800; letter-spacing: .2em; }
h1 { margin: 0; font-size: clamp(1.8rem, 6vw, 2.8rem); line-height: 1.15; }
.period { display: inline-flex; gap: 10px; align-items: center; margin-top: 22px; padding: 9px 16px; border: 1px solid #435a75; border-radius: 999px; color: #becbdd; font-weight: 750; letter-spacing: .08em; }
.period span { color: #f7c85b; font-size: 1.25rem; }

.teams { display: grid; grid-template-columns: 1fr auto 1fr; gap: clamp(10px, 3vw, 24px); align-items: center; margin: 36px 0; }
.team { min-width: 0; padding: clamp(16px, 3vw, 26px) 12px; text-align: center; border: 1px solid #435a75; border-radius: 14px; background: #142137; }
.team h2 { margin: 0; font-size: 1rem; letter-spacing: .12em; }
.team-a h2 { color: #65d8c1; }
.team-b h2 { color: #f7c85b; }
.score { display: block; margin: 12px 0 18px; color: #f5f4e9; font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace; font-size: clamp(3rem, 13vw, 5.5rem); font-weight: 800; line-height: 1; font-variant-numeric: tabular-nums; text-shadow: 0 0 24px #65d8c133; }
.versus { color: #91a2b9; font-size: .9rem; font-weight: 850; letter-spacing: .12em; }
.score-controls { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; }
button { min-height: 48px; padding: 8px 10px; border: 1px solid #526985; border-radius: 9px; color: #f5f4e9; background: #263b57; font: inherit; font-weight: 800; cursor: pointer; transition: transform .12s ease, background-color .12s ease, border-color .12s ease, box-shadow .12s ease; }
.score-controls button:hover { border-color: #65d8c1; background: #31516a; }
button:focus-visible { outline: 3px solid #f7c85b; outline-offset: 3px; }
button:active:not(:disabled) { transform: translateY(2px) scale(.98); }
button:disabled { cursor: not-allowed; opacity: .45; }
.board-footer { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }
.undo { background: #263b57; }
.reset { border-color: #b97768; background: #573b43; }
.reset:hover { border-color: #f7c85b; background: #70464a; }
.hint { grid-column: 1 / -1; margin: 4px 0 0; color: #aab8c9; text-align: center; font-size: .9rem; }

@media (max-width: 480px) {
  .board { padding: 22px 16px; }
  .teams { gap: 8px; margin: 28px 0; }
  .team { padding: 18px 8px; }
  .team h2 { font-size: .9rem; }
  .score-controls { gap: 5px; }
  .score-controls button { min-height: 46px; padding: 6px 4px; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { transition-duration: .01ms !important; }
}

const scores = { a: 0, b: 0 };
const history = [];
let period = 1;

const scoreEls = {
  a: document.getElementById('score-a'),
  b: document.getElementById('score-b')
};
const periodEl = document.getElementById('period');
const undoButton = document.getElementById('undo');

function render() {
  scoreEls.a.textContent = scores.a;
  scoreEls.b.textContent = scores.b;
  periodEl.textContent = period;
  undoButton.disabled = history.length === 0;
}

document.querySelectorAll('[data-team][data-points]').forEach((button) => {
  button.addEventListener('click', () => {
    const team = button.dataset.team;
    const points = Number(button.dataset.points);
    history.push({ team, points });
    scores[team] += points;
    render();
  });
});

undoButton.addEventListener('click', () => {
  const change = history.pop();
  if (!change) return;
  scores[change.team] -= change.points;
  render();
});

document.getElementById('reset').addEventListener('click', () => {
  scores.a = 0;
  scores.b = 0;
  period = 1;
  history.length = 0;
  render();
});

// The period display advances when the current period value is activated.
periodEl.addEventListener('click', () => {
  period = period === 4 ? 1 : period + 1;
  render();
});

render();
